private void analyzeDocument(String filename) throws IOException {
  File inputFile = new File(filename);
  Scanner scan = new Scanner(inputFile).useDelimiter("[^a-zA-Z]+");

  while (scan.hasNext()) {
    String word = scan.next().toLowerCase();
    if (countWords.get(word) == null) { countWords.put(word, 1); }
    else {
       Integer count = countWords.get(word);
       countWords.put(word, count+1);
    }
  }
}

