public class Course {
  String prefix; 
// Course prefix: e.g. MATH
  int number; 
// Course number: e.g. 1324
  . . .
  boolean equals(Course c) {
    return (prefix == c.prefix && number == c.number);
  }
  int hashCode() { return prefix.hashCode() + number; }
}
